{"task": "Find all ERROR level logs containing error codes in format E123-456", "sql": "SELECT * FROM logs WHERE level = 'ERROR' AND regexp_like(message, 'E[0-9]+-[0-9]+')"}
{"task": "Count log messages by service that contain error codes", "sql": "SELECT service, COUNT(*) as error_count FROM logs WHERE regexp_like(message, 'E[0-9]+-[0-9]+') GROUP BY service"}
{"task": "Identify unique error codes from all log messages", "sql": "SELECT DISTINCT regexp_extract(message, 'E[0-9]+-[0-9]+', 0) as error_code FROM logs WHERE regexp_like(message, 'E[0-9]+-[0-9]+')"}
{"task": "Find warning logs with error codes that occurred in last hour", "sql": "SELECT * FROM logs WHERE level = 'WARNING' AND regexp_like(message, 'E[0-9]+-[0-9]+') AND ts > now() - INTERVAL '1 hour'"}
{"task": "Match error codes in both logs and events tables using JOIN", "sql": "SELECT l.ts, l.message, e.path FROM logs l INNER JOIN events e ON regexp_like(l.message, 'E[0-9]+-[0-9]+') WHERE regexp_like(e.path, '/api/.*E[0-9]+-[0-9]+.*')"}
{"task": "Categorize log messages based on error code format", "sql": "SELECT ts, message, CASE WHEN regexp_like(message, 'E[0-9]{3}-[0-9]{3}') THEN 'Standard' ELSE 'Other' END as code_type FROM logs WHERE regexp_like(message, 'E[0-9]+-[0-9]+')"}
{"task": "Find log messages with error codes that have specific service", "sql": "SELECT * FROM logs WHERE service = 'auth-service' AND regexp_like(message, 'E[0-9]+-[0-9]+')"}
{"task": "Count total occurrences of each error code pattern in logs", "sql": "SELECT regexp_extract(message, 'E[0-9]+-[0-9]+', 0) as error_code, COUNT(*) as frequency FROM logs WHERE regexp_like(message, 'E[0-9]+-[0-9]+') GROUP BY error_code ORDER BY frequency DESC"}
{"task": "Search for log messages with multiple different error codes", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'E[0-9]+-[0-9]+.*E[0-9]+-[0-9]+')"}
{"task": "Find error code patterns that appear in both logs and events paths", "sql": "SELECT DISTINCT l.message, e.path FROM logs l CROSS JOIN events e WHERE regexp_like(l.message, 'E[0-9]+-[0-9]+') AND regexp_like(e.path, '.*E[0-9]+-[0-9]+.*')"}

